package dev.dres.mgmt.cache

import com.github.kokorin.jaffree.ffmpeg.FFmpeg
import com.github.kokorin.jaffree.ffmpeg.UrlInput
import com.github.kokorin.jaffree.ffmpeg.UrlOutput
import dev.dres.DRES
import dev.dres.data.model.config.Config
import dev.dres.api.rest.handler.system.SystemStatusRegistry
import dev.dres.api.rest.types.system.SystemStatus
import dev.dres.api.rest.types.system.SystemStatusLevel
import dev.dres.data.model.media.DbMediaItem
import dev.dres.data.model.media.DbMediaType
import dev.dres.data.model.media.MediaItemType
import dev.dres.data.model.run.DbEvaluation
import dev.dres.data.model.run.DbEvaluationStatus
import dev.dres.utilities.CompletedFuture
import dev.dres.utilities.FailedFuture
import jetbrains.exodus.database.TransientEntityStore
import jetbrains.exodus.kotlin.synchronized
import kotlinx.dnq.query.asSequence
import kotlinx.dnq.query.filter
import kotlinx.dnq.query.flatMapDistinct
import org.slf4j.LoggerFactory
import org.slf4j.MarkerFactory
import java.awt.Image
import java.awt.image.BufferedImage
import java.io.IOException
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.StandardOpenOption
import java.util.concurrent.*
import javax.imageio.ImageIO
import kotlin.io.path.*

/**
 * A [CacheManager] used to manager and generate, access and manage cached image and video previews.
 *
 * @author Ralph Gasser
 * @version 1.0.0
 */
class CacheManager(private val config: Config, private val store: TransientEntityStore) {
    companion object {
        private val LOGGER = LoggerFactory.getLogger(PreviewImageFromVideoRequest::class.java)
        private val MARKER = MarkerFactory.getMarker("FFMPEG")
    }

    /** Directory containing FFmpeg binaries, resolved lazily to support installation at runtime. */
    private val ffmpegBin: Path?
        get() = this.config.cache.ffmpegPath()

    private fun requireFFmpeg(): Path = ffmpegBin
        ?: throw IllegalStateException("FFmpeg is unavailable. Run 'setup ffmpeg' in the DRES console or install FFmpeg system-wide.")

    /** The [Path] to the cache location. */
    private val cacheLocation = DRES.CONFIG.cache.cachePath

    /** A [ConcurrentHashMap] of all [Path]s* that are currently being calculated. */
    private val inTransit = ConcurrentHashMap<Path,Future<Path>>()

    /** The [ExecutorService] used by this [CacheManager]. */
    private val executor: ExecutorService = Executors.newFixedThreadPool(this.config.cache.maxRenderingThreads)

    init {
        val ffmpegDirectory = this.ffmpegBin
        if (ffmpegDirectory == null) {
            System.err.println("WARNING: FFmpeg was not found. Video preview generation is unavailable.")
            System.err.println("         Run 'setup ffmpeg' in the DRES console or install FFmpeg system-wide.")
        } else {
            println("Found FFmpeg at $ffmpegDirectory...")
        }
        if (!Files.exists(cacheLocation)) {
            println("Created cache location at ${this.cacheLocation}...")
            Files.createDirectories(cacheLocation)
        }
    }

    /**
     * Generates a preview image from a Path to an external image.
     *
     * @param imagePath the source path.
     * @return [Future] of the [Path] to the generated image.
     */
    fun asyncPreviewImage(imagePath: Path): Future<Path> {
        val output = this@CacheManager.cacheLocation.resolve("${imagePath.fileName}.jpg")
        return submitOnce(output, "preview image") { PreviewImageFromImageRequest(imagePath, output) }
    }

    /**
     * Generates a preview image from a [DbMediaItem].
     *
     * @param item The [DbMediaItem] to generate the preview image from. Must be of [DbMediaType.VIDEO] or [DbMediaType.IMAGE].
     * @param timestamp The timestamp in milliseconds to generate the preview image from. Defaults to 0.
     * @return [Future] of the [Path] to the generated image.
     */
    fun asyncPreviewImage(item: DbMediaItem, timestamp: Long = 0): Future<Path> {
        require(timestamp >= 0) { "Frame numbers cannot be negative." }
        /** The output path generated by this [PreviewImageFromVideoRequest]. */
        val output = this@CacheManager.cacheLocation.resolve("${item.mediaItemId}_${timestamp}-${timestamp}.jpg")
        return submitOnce(output, "preview image") {
            when (item.type()) {
                MediaItemType.IMAGE -> PreviewImageFromImageRequest(item.pathToOriginal(), output)
                MediaItemType.VIDEO -> if (timestamp <= item.durationMs!!) { //bounds check
                    PreviewImageFromVideoRequest(item.pathToOriginal(), output, timestamp)
                } else {
                    throw PreviewUnavailable("Requested time is outside of video.")
                }
                else -> throw PreviewUnavailable("Cannot generate a preview image from a media item that is neither a video nor an image.")
            }
        }
    }

    /**
     * Generates a preview video from a [DbMediaItem].
     *
     * @param item The [DbMediaItem] to generate the preview video from. Must be of [DbMediaType.VIDEO].
     * @param start The start position in milliseconds to generate the preview video from.
     * @param start The end position in milliseconds to generate the preview video from. Defaults to 0.
     * @return [Future] of the [Path] to the generated video.
     */
    fun asyncPreviewVideo(item: DbMediaItem, start: Long, end: Long): Future<Path> {
        require(start >= 0) { "Start timestamp cannot be negative." }
        require(end > start) { "End timestamp must be greater than start." }
        val clampedEnd = if (item.durationMs != null) minOf(end, item.durationMs!!) else end
        /** The output path generated by this [PreviewImageFromVideoRequest]. */
        val output = this@CacheManager.cacheLocation.resolve("${item.mediaItemId}_${start}-${clampedEnd}.mp4")
        return submitOnce(output, "preview video") {
            when (item.type()) {
                MediaItemType.VIDEO -> if (start < item.durationMs!!) {
                    PreviewVideoFromVideoRequest(item.pathToOriginal(), output, start, clampedEnd)
                } else {
                    throw PreviewUnavailable("Requested time is outside of video.")
                }
                else -> throw PreviewUnavailable("Cannot generate a video preview from a media item that is not a video.")
            }
        }
    }
    /**
     * Generates a preview video from a Path.
     *
     * @param item The [DbMediaItem] to generate the preview video from. Must be of [DbMediaType.VIDEO].
     * @param start The start position in milliseconds to generate the preview video from.
     * @param start The end position in milliseconds to generate the preview video from. Defaults to 0.
     * @return [Future] of the [Path] to the generated video.
     */
    fun asyncPreviewVideo(input: Path, start: Long, end: Long): Future<Path> {
        require(start >= 0) { "Start timestamp cannot be negative." }
        require(end > start) { "End timestamp must be greater than start." }
        /** The output path generated by this [PreviewImageFromVideoRequest]. */
        val output = this@CacheManager.cacheLocation.resolve("${input.fileName}_${start}-${end}.mp4")
        return submitOnce(output, "preview video") { PreviewVideoFromVideoRequest(input, output, start, end) }
    }

    /** Raised by a [submitOnce] job that cannot run, e.g. because a timestamp lies outside the video. */
    private class PreviewUnavailable(message: String) : Exception(message)

    /**
     * Returns a finished or in-progress [Future] for [output], starting at most one job for it.
     *
     * The existence check, the in-transit lookup and the submission all happen under one lock. They used to
     * be split - the lookup outside, the submission inside - so two callers asking for the same preview at
     * the same time could both miss the entry and both submit an FFmpeg job for the same output path, which
     * then wrote over each other's scratch files and wasted a render each.
     *
     * Atomic publication (see [AbstractPreviewRequest.publish]) means an existing file is a complete file,
     * so no separate "is it still being written" state is needed here.
     *
     * @param output The cache file the job produces.
     * @param description What is rendered, used in error messages.
     * @param job Builds the rendering job.
     * @return A [CompletedFuture] with the cached file, the in-flight job, or a [FailedFuture].
     */
    private fun submitOnce(output: Path, description: String, job: () -> AbstractPreviewRequest): Future<Path> =
        synchronized {
            if (Files.exists(output)) {
                this.inTransit.remove(output)
                return@synchronized CompletedFuture(output)
            }
            this.inTransit[output]?.let { return@synchronized it }
            try {
                val ret = this.executor.submit(job())
                this.inTransit[output] = ret
                ret
            } catch (e: PreviewUnavailable) {
                FailedFuture(e.message ?: "Cannot render the $description.")
            } catch (e: Throwable) {
                LOGGER.error("Could not submit the $description for ${output.fileName}.", e)
                FailedFuture("Could not generate the $description: ${e.message}")
            }
        }

    /**
     * Cleans the cache directory associated with this [CacheManager]. The cleanup mechanism makes sure, that all
     * as part of an ongoing evaluation are preserved and not deleted.
     *
     * Requires an active transaction.
     */
    fun cleanup() = try {
        /*
         * Collect the cache files the active evaluations need. The previous version built names as
         * "${mediaItemId}_${start}-${end}" with no extension, while the files are written as
         * "<id>_<start>-<end>.mp4" / ".jpg" (and images as "<id>_<ts>-<ts>.jpg"), so the names never
         * matched, nothing was protected, and every preview older than five minutes was deleted - including
         * previews of runs that were still going.
         */
        val blackList = mutableSetOf<Path>()
        this.store.transactional(true) {
            val videoPreviews = mutableSetOf<Pair<String, Pair<Long, Long>>>()
            val imagePreviews = mutableSetOf<Pair<String, Long>>()

            DbEvaluation.filter { it.status eq DbEvaluationStatus.ACTIVE }.asSequence().forEach { evaluation ->
                val tasks = evaluation.template.tasks

                tasks.flatMapDistinct { it.hints }.filter { it.item ne null }.asSequence().forEach { hint ->
                    val itemId = hint.item!!.mediaItemId
                    if (itemId == null) return@forEach
                    val start = hint.start ?: 0L
                    val end = hint.end
                    if (end == null) imagePreviews.add(itemId to start) else videoPreviews.add(itemId to (start to end))
                }

                tasks.flatMapDistinct { it.targets }.filter { it.item ne null }.asSequence().forEach { target ->
                    val itemId = target.item!!.mediaItemId
                    if (itemId == null) return@forEach
                    val range = target.range
                    if (range == null) imagePreviews.add(itemId to (target.start ?: 0L))
                    else videoPreviews.add(itemId to (range.start.toMilliseconds() to range.end.toMilliseconds()))
                }
            }

            videoPreviews.forEach { (itemId, range) ->
                blackList.add(this@CacheManager.cacheLocation.resolve("${itemId}_${range.first}-${range.second}.mp4"))
            }
            imagePreviews.forEach { (itemId, timestamp) ->
                blackList.add(this@CacheManager.cacheLocation.resolve("${itemId}_${timestamp}-${timestamp}.jpg"))
            }
        }

        /* Delete all files that are neither protected nor currently being written. */
        Files.walk(this.cacheLocation).use { walk ->
            walk.sorted(Comparator.reverseOrder()).forEach {
                if (this.inTransit.containsKey(it) || blackList.contains(it)) {
                    return@forEach
                }
                val time = Files.getLastModifiedTime(it)
                if ((System.currentTimeMillis() - time.toMillis()) > 300000L) {
                    Files.delete(it)
                }
            }
        }
    } catch(e: Throwable) {
        LOGGER.warn("Failed to cleanup cache directory ${this.cacheLocation}: ${e.message}")
    }

    /**
     * Clears the cache directory associated with this [CacheManager].
     */
    fun clear() = try {
        Files.walk(this.cacheLocation).use { walk ->
            walk.sorted(Comparator.reverseOrder()).forEach {
                Files.delete(it)
            }
        }
    } catch(e: Throwable) {
        LOGGER.warn("Failed to clear cache directory ${this.cacheLocation}: ${e.message}")
    }

    /**
     * Stops this [CacheManager] and all requests that are in transit.
     */
    fun stop() {
        this.executor.shutdown()
        this.executor.awaitTermination(5000, TimeUnit.MILLISECONDS)
    }

    /**
     * Utility method to convert from milliseconds to timecode representation.
     *
     * @param ms The timestamp in milliseconds.
     * @return The timecode [String].
     */
    private fun millisecondToTimestamp(ms: Long): String {
        val hours = ms / (1000 * 3600)
        val minutes = (ms % (1000 * 3600)) / (60_000)
        val seconds = (ms % 60_000) / 1000
        val milliseconds = ms % 1000
        return "$hours:${"%02d".format(minutes)}:${"%02d".format(seconds)}.${"%03d".format(milliseconds)}"
    }

    /**
     * A [Callable] that generates a preview image from an image file.
     */
    inner class PreviewImageFromImageRequest constructor(input: Path, output: Path, private val size: Int = this@CacheManager.config.cache.previewImageMaxSize): AbstractPreviewRequest(input, output) {

        override fun call(): Path = try {/* Try to read image. */
            this.publish { scratch ->
                Files.newInputStream(this.input, StandardOpenOption.READ).use { i ->
                    val image = ImageIO.read(i)

                    /* Scale image to a maximum of 500x500 pixels. */
                    val scaled: Image = if (image.width > image.height) {
                        image.getScaledInstance(size, -1, Image.SCALE_DEFAULT)
                    } else {
                        image.getScaledInstance(-1, size, Image.SCALE_DEFAULT)
                    }
                    val outputImage = BufferedImage(scaled.getWidth(null), scaled.getHeight(null), BufferedImage.TYPE_INT_RGB)
                    outputImage.graphics.drawImage(scaled, 0, 0, null)

                    Files.newOutputStream(scratch, StandardOpenOption.CREATE, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING).use { o ->
                        ImageIO.write(outputImage, "jpg", o)
                    }
                }
            }
        } catch (e: Exception) {
            LOGGER.error("Error in FFMpeg: ${e.message}", e)
            throw e
        } finally {
            this@CacheManager.inTransit.remove(this.output) /* Remove this PreviewImageFromVideoRequest. */
        }
    }

    /**
     * A [Callable] that generates a preview image from a video file.
     */
    inner class PreviewImageFromVideoRequest constructor(input: Path, output: Path, private val start: Long, private val size: Int = this@CacheManager.config.cache.previewImageMaxSize): AbstractPreviewRequest(input, output) {
        override fun call(): Path = try {
            this.publish { scratch ->
                FFmpeg.atPath(this@CacheManager.requireFFmpeg())
                    .addArguments("-ss", millisecondToTimestamp(this.start))
                    .addInput(UrlInput.fromPath(this.input))
                    .addOutput(UrlOutput.toPath(scratch))
                    .setOverwriteOutput(true)
                    .addArguments("-frames:v", "1")
                    .addArguments("-filter:v", "scale=${this.size}:-1")
                    .setOutputListener { l -> LOGGER.debug(MARKER, l); }
                    .execute()
            }
        } catch (e: Exception) {
            LOGGER.error("Error in FFMpeg: ${e.message}")
            throw e
        } finally {
            this@CacheManager.inTransit.remove(this.output) /* Remove this PreviewImageFromVideoRequest. */
        }
    }

    /**
     * A [Callable] that generates a preview video from a video file.
     */
    inner class PreviewVideoFromVideoRequest constructor(input: Path, output: Path, private val start: Long, private val end: Long): AbstractPreviewRequest(input, output){
        override fun call(): Path = try {
            val startTimecode = millisecondToTimestamp(this.start)
            val endTimecode = millisecondToTimestamp(this.end)
            LOGGER.info(MARKER, "Start rendering segment for video $input from $startTimecode to $endTimecode")
            /* Rendered into a scratch file and published atomically, so readers never see a partial video. */
            this.publish { scratch ->
                FFmpeg.atPath(this@CacheManager.requireFFmpeg())
                    .addArguments("-ss", startTimecode)
                    .addInput(UrlInput.fromPath(this.input))
                    .addOutput(UrlOutput.toPath(scratch))
                    .setOverwriteOutput(true)
                    .addArguments("-to", endTimecode)
                    .addArguments("-c:v", "libx264")
                    .addArguments("-c:a", "aac")
                    .addArguments("-b:v", "2000k")
                    .addArguments("-filter:v", "scale=${this@CacheManager.config.cache.previewVideoMaxSize}:-1")
                    .addArguments("-tune", "zerolatency")
                    .addArguments("-preset", "slow")
                    .setOutputListener { l -> LOGGER.debug(MARKER, l); }
                    .execute()
            }

            SystemStatusRegistry.clear(SystemStatusRegistry.FFMPEG_VIDEO_RENDER_FAILED)
            this.output
        } catch (e: Exception) {
            LOGGER.error("Error in FFMpeg: ${e.message}", e)
            if (this@CacheManager.ffmpegBin != null) {
                SystemStatusRegistry.publish(
                    SystemStatus(
                        code = SystemStatusRegistry.FFMPEG_VIDEO_RENDER_FAILED,
                        level = SystemStatusLevel.WARNING,
                        message = "FFmpeg failed to render a query video preview. Check the server logs for details."
                    )
                )
            }
            /* Leave any previously cached preview in place: publish() never replaced it. */
            throw e
        } finally {
            this@CacheManager.inTransit.remove(this.output) /* Remove this PreviewImageFromVideoRequest. */
        }
    }
}
